import{_ as o,o as d,c,aS as t}from"./chunks/framework.DsJaIkSj.js";const u=JSON.parse('{"title":"UI 公共 interface","description":"","frontmatter":{},"headers":[],"relativePath":"contracts/ui-public-interface.md","filePath":"contracts/ui-public-interface.md","lastUpdated":null}'),a={name:"contracts/ui-public-interface.md"};function r(n,e,l,i,s,p){return d(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="ui-公共-interface" tabindex="-1">UI 公共 interface <a class="header-anchor" href="#ui-公共-interface" aria-label="Permalink to &quot;UI 公共 interface&quot;">​</a></h1><p>状态：当前权威（新增与变更公共契约的治理口径）。当前可发布的组件及子路径仍以 <code>packages/ui/package.json</code> 的 <code>exports</code>、对应 <code>.d.ts</code> 和发布产物为准。</p><h2 id="qy-所有权" tabindex="-1">Qy 所有权 <a class="header-anchor" href="#qy-所有权" aria-label="Permalink to &quot;Qy 所有权&quot;">​</a></h2><p>业务侧依赖的是 Qy 定义的组件名称、props、emits、slots、expose、默认行为和 tokens。每项新增或变更都必须在 Qy 语义下命名、文档化并以组件测试/声明验证；不能把底层库名称、默认行为或实现对象直接提升为业务契约。</p><table tabindex="0"><thead><tr><th>契约面</th><th>Qy 负责的内容</th><th>不应新增为公共依赖的内容</th></tr></thead><tbody><tr><td>props / defaults</td><td>输入语义、默认值与兼容策略</td><td>Element Plus prop 类型、隐式底层默认值</td></tr><tr><td>emits</td><td>事件名、触发时机和 payload</td><td>厂商私有事件或回调对象</td></tr><tr><td>slots</td><td>Qy 命名、上下文与兼容承诺</td><td>底层组件的未封装 slot 细节</td></tr><tr><td>expose</td><td>Qy 明确承诺的方法和返回语义</td><td>组件实例、私有 DOM、VNode/Node/Store</td></tr><tr><td>tokens</td><td>Qy tokens 及其视觉语义</td><td>业务必须直接使用的 <code>--el-*</code> 变量</td></tr></tbody></table><h2 id="当前实现与历史债务" tabindex="-1">当前实现与历史债务 <a class="header-anchor" href="#当前实现与历史债务" aria-label="Permalink to &quot;当前实现与历史债务&quot;">​</a></h2><p>UI 当前维护 Vue 3 + Element Plus implementation，不是已经多框架兼容的 renderer 层。Element Plus 依赖和内部 import 可以存在；新增公共 API 不得扩大厂商类型、实例、私有 DOM/VNode/Node/Store、私有事件或 <code>--el-*</code> 漏泄。</p><p>现有 <code>packages/ui/qy-input/index.d.ts</code> 的 <code>QyInputProps</code> / <code>QyInputType</code> / <code>autosize</code>，以及 <code>packages/ui/qy-input-number/index.d.ts</code> 的 <code>QyInputNumberProps</code>，仍引用或继承 Element Plus 类型。这是已登记的兼容债务：后续按模块审查、迁移和验证；本文件不宣称其已经框架中立，也不要求本阶段批量修复。</p><h2 id="变更检查" tabindex="-1">变更检查 <a class="header-anchor" href="#变更检查" aria-label="Permalink to &quot;变更检查&quot;">​</a></h2><ol><li>先核对根入口或子路径 exports、对应声明、现有 README 与消费者用法。</li><li>变更 Qy-owned props、emits、slots、expose、defaults 或 tokens 时，补充最小行为/类型证据并保持兼容性口径。</li><li>仅当真实行为差异或复杂边界需要时，建立内部 adapter seam；renderer 决策以 <a href="./../adr/2026-08-06-current-element-implementation-and-future-renderer-seam">当前 Element Plus implementation ADR</a> 为准。</li></ol><p>本契约不决定包版本、构建格式或 npm 解析；这些见 <a href="./package-exports-and-runtime">包 exports 与宿主 runtime</a>。</p><h2 id="qypopconfirm" tabindex="-1">QyPopconfirm <a class="header-anchor" href="#qypopconfirm" aria-label="Permalink to &quot;QyPopconfirm&quot;">​</a></h2><p><code>QyPopconfirm</code> 的稳定面是 Qy-owned 的确认语义：<code>title</code>、受控/非受控 <code>open</code>、<code>confirmLoading</code>、<code>closeOnConfirm</code>、<code>variant</code>、<code>confirmType</code>、<code>placement</code> 与 <code>width</code>。插槽仅承诺 <code>reference</code>、<code>title</code> 和 <code>icon</code>；事件为 <code>update:open</code>、<code>open-change</code>、<code>confirm</code>、<code>cancel</code> 与携带 Qy 关闭原因的 <code>close(reason)</code>。业务侧不依赖 Element Plus 实例、原始事件对象、teleport/popper 参数或底层 CSS 变量。</p><h2 id="qydialog" tabindex="-1">QyDialog <a class="header-anchor" href="#qydialog" aria-label="Permalink to &quot;QyDialog&quot;">​</a></h2><p><code>QyDialog</code> 的稳定面是受控 <code>open</code>、<code>update:open</code>、<code>open-change</code>、<code>confirm</code>、<code>cancel</code>、<code>close(reason)</code>、<code>opened</code> 和 <code>closed</code>。<code>QyDialogCloseReason</code> 冻结为 <code>confirm | cancel | header | escape | overlay | external</code>。默认 footer 由 <code>showFooter</code>、<code>showConfirm</code>、<code>showCancel</code>、<code>confirmText</code>、<code>cancelText</code>、<code>confirmLoading</code> 和 <code>confirmDisabled</code> 控制；宿主持有异步业务并在成功后关闭，Dialog 不接收任意业务 Promise。</p><p>宽度、顶部距离、全屏、最小化、销毁、拖拽、锁滚动和显式关闭策略均使用 Qy-owned props。<code>header</code>、<code>footer</code>、<code>footer-left</code> 和 <code>footer-append</code> 是稳定 slot；唯一公开方法为 <code>handleMinimize()</code>。公共类型不暴露 Element Plus props、实例、原始事件、DOM/VNode/Node/Store 或 <code>--el-*</code>。</p><p>旧 <code>modelValue</code>、字符串 <code>layout</code>、<code>confirmProps</code>、<code>ok</code> 和任意 Element attrs 由独立 <code>@qynpm/qy-dialog-legacy</code> 薄 adapter 过渡承接，不进入 QyDialog 当前契约，也不作为新业务 API。</p><h2 id="qywatermark" tabindex="-1">QyWatermark <a class="header-anchor" href="#qywatermark" aria-label="Permalink to &quot;QyWatermark&quot;">​</a></h2><p><code>QyWatermark</code> 的稳定面是容器内平铺水印：<code>content</code>、<code>image</code>、<code>zIndex</code>、<code>rotate</code>、<code>width</code>、<code>height</code>、<code>gap</code>、<code>offset</code> 和 Qy-owned <code>font</code>；只承诺 <code>default</code> 插槽。图片优先，加载失败回退到文字；覆盖层不接收指针事件，容器变化和当前 renderer 可观察到的节点篡改由内部实现恢复。业务侧只依赖安全容器属性 <code>class</code>、<code>style</code>、<code>id</code>、<code>title</code>、<code>role</code>、<code>data-*</code>、<code>aria-*</code>，不依赖 Element Plus props、实例、DOM、事件、expose 或 CSS 变量。</p><h2 id="qyiframe" tabindex="-1">QyIframe <a class="header-anchor" href="#qyiframe" aria-label="Permalink to &quot;QyIframe&quot;">​</a></h2><p><code>QyIframe</code> 的稳定面是带必填 <code>src</code> 与无障碍 <code>title</code> 的原生嵌入页面；二者去除首尾空白后任一为空时不渲染 iframe。<code>src</code> 变化时更新地址，<code>reloadKey?: string | number</code> 变化时重建 iframe，使相同地址也可受控 reload。组件支持 <code>loading</code>、<code>sandbox</code>、<code>allow</code>、<code>referrerPolicy</code>、<code>allowFullscreen</code>，<code>load</code> 与 <code>error</code> 仅为无参数通知，不暴露 DOM Event。组件填满宿主提供的容器，不感知应用头部高度，不覆盖全局 resize 监听，不模拟加载时长，也不接管会话、地址白名单或跨域通信。业务侧只依赖安全根属性，不依赖 DOM ref、Element Plus 或宿主运行时对象。</p>',21)])])}const f=o(a,[["render",r]]);export{u as __pageData,f as default};
